from itertools import product

N = 4
dom = range(N)

def subsets():
    for bits in product([0, 1], repeat=N):
        yield frozenset(i for i in dom if bits[i])

def some_not(X, Y):   # some X are not Y
    return any(i in X and i not in Y for i in dom)

def all_in(X, Y):     # all X are Y
    return all((i not in X) or (i in Y) for i in dom)

models = [(X, Y) for X in subsets() for Y in subsets()]

# Original: Some G are not C  =>  not all C are G   (G=good, C=cheap)
def original(G, C):
    return (not some_not(G, C), not all_in(C, G))   # (premise_true, concl_true)

# Option forms, as functions of (X, Y) with premise "some X are not Y"
forms = {
