    "B": lambda X, Y: (some_not(X, Y), not all_in(X, Y)),       # some A not B => not all A are B
    "C": lambda X, Y: (some_not(X, Y), some_not(Y, X)),         # some motive not effect => some effect not motive
    "D": lambda X, Y: (some_not(X, Y), not all_in(Y, X)),       # some S not Ca => not all Ca are S
}

